@php
    $money = fn ($value) => number_format((float) $value, 2);
    $labels = array_replace($labels ?? [], ['contract_file_client'=>'File process', 'contract_file'=>'File process cost', 'contract_file_service_cost'=>'File service cost', 'contract_file_client_adjustment'=>'File process adjustment', 'contract_file_vendor_adjustment'=>'File cost adjustment']);
    $companyName = $company?->name ?: 'EPAL TRAVELS & CONSULTANCY';
    $highlight = $highlight ?? collect();
    $newIds = $highlight->pluck('id')->flip();
    $date = fn ($value) => $value ? \Carbon\Carbon::parse($value)->format('d M Y') : null;
    $periodFrom = $date($date_from ?? null) ?: 'Start';
    $periodTo = $date($date_to ?? null) ?: now()->format('d M Y');
    $period = ($date_from ?? null) || ($date_to ?? null) ? "{$periodFrom} - {$periodTo}" : 'All Time';
    $totalDebit = (float) $rows->sum('debit');
    $totalCredit = (float) $rows->sum('credit');
    $balanceLabel = abs($closing) < .005 ? 'Settled' : ($closing > 0 ? ($side === 'receivable' ? 'Receivable' : 'Payable') : 'Advance');
    try { $balanceWords = ucfirst((new \NumberToWords\NumberToWords())->getNumberTransformer('en')->toWords((int) abs($closing))) . ' Taka'; }
    catch (\Throwable) { $balanceWords = 'BDT ' . $money(abs($closing)); }
    $logoPath = $company?->logo ? public_path($company->logo) : null;
    if (!$logoPath || !is_file($logoPath)) $logoPath = public_path('logo.png');
    $logo = is_file($logoPath) ? 'data:image/' . pathinfo($logoPath, PATHINFO_EXTENSION) . ';base64,' . base64_encode(file_get_contents($logoPath)) : null;
